function lesson(input) {
  const steps = input.steps.map(([title, body]) => ({ title, body }))
  return {
    id: input.id,
    title: input.title,
    summary: input.summary,
    keywords: [...new Set([input.course, input.title, ...(input.keywords || [])])],
    product: input.product,
    course: input.course,
    roles: input.roles || [],
    features: input.features || [],
    permissions: input.permissions || [],
    minutes: input.minutes || Math.max(6, steps.length + 2),
    outcome: input.outcome || input.success,
    who: input.who || productWho[input.product],
    before: input.before || ['A signed-in MarketSync account in the correct workspace', 'A real training record or approved test record to work with'],
    steps,
    success: input.success,
    automatic: input.automatic || productAutomatic[input.product],
    problems: input.problems || productProblems[input.product],
    safety: input.safety || 'Use approved training data on staging. Confirm the customer, vehicle, dealership, amount, and recipient before saving or sending anything.',
    verified,
    videoStatus: 'ready',
  }
}

